// The credit a purchase records for its supplier is marked source='purchase',
// so these never touch a manual entry that merely links to the purchase.
func (q *Queries) UpdatePurchaseLedgerCredit(ctx context.Context, arg UpdatePurchaseLedgerCreditParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePurchaseLedgerCredit,
		arg.SupplierID,
		arg.Date,
		arg.BsDate,
		arg.Amount,
		arg.Description,
		arg.StockInID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
